topic_id = #{topicId}, slug = #{slug}, title = #{title}, summary = #{summary}, tags = #{tags}, source_filename = #{sourceFilename}, current_version = #{currentVersion}, content_md = #{contentMd}, content_hash = #{contentHash}, block_count = #{blockCount}, word_count = #{wordCount}, sort_order = #{sortOrder},
