mapper.select:
SELECT d.id, d.title, d.topic_id, d.content_md
FROM doc d
WHERE d.owner_id = #{ownerId}
  AND (d.title LIKE #{pattern} ESCAPE '\\' OR d.content_md LIKE #{pattern} ESCAPE '\\')
ORDER BY d.updated_at DESC
